import "server-only";
import { randomBytes } from "node:crypto";
import { and, eq, gte, inArray, lt } from "drizzle-orm";
import { db, schema as s } from "@/db";
import { cancelByDedupeKey, enqueue } from "./outbox";
import { redis } from "./redis";
import { localTimeToUtc, isoWeekday, slotsForDay, type Range } from "./slots";

// ---------- Redis slot holds (stop two clients checking out the same slot) ----------

const holdKey = (staffId: string, startMs: number) => `hold:${staffId}:${startMs}`;

export type Hold = { token: string; endMs: number };

/** Try to place a hold on a slot. Returns a token, or null if already held. */
export async function createHold(
  staffId: string,
  slot: Range,
  ttlSec: number,
): Promise<string | null> {
  const token = randomBytes(16).toString("hex");
  const ok = await redis().set(
    holdKey(staffId, slot.startMs),
    JSON.stringify({ token, endMs: slot.endMs } satisfies Hold),
    "EX",
    ttlSec,
    "NX",
  );
  return ok ? token : null;
}

/** Active holds for a master within [fromMs, toMs). */
// ponytail: KEYS-scan per request is O(active holds); holds expire in minutes,
// so the set stays tiny. Move to a per-staff zset if a business ever needs it.
export async function listHolds(staffId: string, fromMs: number, toMs: number): Promise<Range[]> {
  const keys = await redis().keys(`hold:${staffId}:*`);
  if (keys.length === 0) return [];
  const values = await redis().mget(keys);
  const out: Range[] = [];
  keys.forEach((k, i) => {
    const raw = values[i];
    if (!raw) return;
    const startMs = Number(k.split(":")[2]);
    const { endMs } = JSON.parse(raw) as Hold;
    if (startMs < toMs && endMs > fromMs) out.push({ startMs, endMs });
  });
  return out;
}

// ---------- Calendar events (Redis pub/sub → SSE) ----------

export const calendarChannel = (businessId: string) => `calendar:${businessId}`;

export async function publishCalendar(businessId: string, event: object): Promise<void> {
  await redis().publish(calendarChannel(businessId), JSON.stringify(event));
}

// ---------- Availability ----------

async function dayWindowFor(
  businessId: string,
  staffId: string,
  dateISO: string,
): Promise<{ open: string; close: string } | null> {
  const weekday = isoWeekday(dateISO);
  const [override] = await db
    .select()
    .from(s.staffHours)
    .where(and(eq(s.staffHours.staffId, staffId), eq(s.staffHours.weekday, weekday)));
  if (override) return { open: override.startTime, close: override.endTime };
  const [base] = await db
    .select()
    .from(s.businessHours)
    .where(and(eq(s.businessHours.businessId, businessId), eq(s.businessHours.weekday, weekday)));
  return base ? { open: base.openTime, close: base.closeTime } : null;
}

export async function getAvailability(opts: {
  businessId: string;
  timeZone: string;
  staffId: string;
  serviceId: string;
  dateISO: string;
}): Promise<Range[]> {
  const { businessId, timeZone, staffId, serviceId, dateISO } = opts;
  const [service] = await db
    .select()
    .from(s.services)
    .where(and(eq(s.services.id, serviceId), eq(s.services.businessId, businessId)));
  if (!service?.isActive) return [];

  const window = await dayWindowFor(businessId, staffId, dateISO);
  if (!window) return [];

  const dayStart = localTimeToUtc(dateISO, "00:00", timeZone);
  const dayEnd = dayStart + 36 * 3600_000; // generous bound; window trims precisely
  const busyRows = await db
    .select({ startAt: s.bookings.startAt, endAt: s.bookings.endAt })
    .from(s.bookings)
    .where(
      and(
        eq(s.bookings.staffId, staffId),
        eq(s.bookings.status, "confirmed"),
        gte(s.bookings.endAt, new Date(dayStart)),
        lt(s.bookings.startAt, new Date(dayEnd)),
      ),
    );
  const busy = busyRows.map((b) => ({ startMs: b.startAt.getTime(), endMs: b.endAt.getTime() }));
  const holds = await listHolds(staffId, dayStart, dayEnd);

  return slotsForDay({
    dateISO,
    timeZone,
    window,
    durationMin: service.durationMin,
    busy,
    holds,
    notBeforeMs: Date.now(),
  });
}

// ---------- Booking creation ----------

export type BookResult =
  | { ok: true; bookingId: string }
  | { ok: false; error: "hold_expired" | "slot_taken" };

export async function createBooking(opts: {
  businessId: string;
  staffId: string;
  serviceId: string;
  slot: Range;
  holdToken: string;
  client: { name: string; phone: string };
}): Promise<BookResult> {
  const { businessId, staffId, serviceId, slot, holdToken, client } = opts;

  // The hold must still be alive and belong to this caller.
  const raw = await redis().get(holdKey(staffId, slot.startMs));
  if (!raw || (JSON.parse(raw) as Hold).token !== holdToken) {
    return { ok: false, error: "hold_expired" };
  }

  const [service] = await db
    .select()
    .from(s.services)
    .where(and(eq(s.services.id, serviceId), eq(s.services.businessId, businessId)));
  if (!service) return { ok: false, error: "slot_taken" };

  // Upsert client by (business, phone)
  const [existing] = await db
    .select()
    .from(s.clients)
    .where(and(eq(s.clients.businessId, businessId), eq(s.clients.phone, client.phone)));
  const clientRow =
    existing ??
    (await db
      .insert(s.clients)
      .values({ businessId, name: client.name, phone: client.phone })
      .returning())[0];

  // Booking, audit trail and outbound messages commit together: a client can
  // never end up with a confirmation for a booking that was rolled back.
  const bookingId = await db.transaction(async (tx) => {
    const [booking] = await tx
      .insert(s.bookings)
      .values({
        businessId,
        staffId,
        serviceId,
        clientId: clientRow.id,
        startAt: new Date(slot.startMs),
        endAt: new Date(slot.endMs),
        status: "confirmed",
        priceKzt: service.priceKzt,
      })
      .returning();

    await tx.insert(s.auditLog).values({
      businessId,
      action: "booking.create",
      entity: "booking",
      entityId: booking.id,
      meta: { staffId, serviceId, startAt: new Date(slot.startMs).toISOString() },
    });

    await enqueue(tx, {
      businessId,
      topic: "booking.confirmed",
      payload: { bookingId: booking.id },
      dedupeKey: `booking.confirmed:${booking.id}`,
    });

    // Reminder the day before; retired automatically if the booking is
    // cancelled before the worker gets to it.
    const remindAt = new Date(slot.startMs - 24 * 3600_000);
    if (remindAt.getTime() > Date.now()) {
      await enqueue(tx, {
        businessId,
        topic: "booking.reminder",
        payload: { bookingId: booking.id },
        dedupeKey: `booking.reminder:${booking.id}`,
        availableAt: remindAt,
      });
    }

    return booking.id;
  });

  await redis().del(holdKey(staffId, slot.startMs));
  await publishCalendar(businessId, { type: "booking.created", bookingId });
  return { ok: true, bookingId };
}

export async function setBookingStatus(opts: {
  businessId: string;
  bookingId: string;
  status: (typeof s.bookingStatuses)[number];
  actorUserId: string;
}): Promise<void> {
  const { businessId, bookingId, status, actorUserId } = opts;
  await db.transaction(async (tx) => {
    const [updated] = await tx
      .update(s.bookings)
      .set({ status })
      .where(and(eq(s.bookings.id, bookingId), eq(s.bookings.businessId, businessId)))
      .returning();
    if (!updated) return;
    await tx.insert(s.auditLog).values({
      businessId,
      actorUserId,
      action: `booking.${status}`,
      entity: "booking",
      entityId: bookingId,
    });

    if (status !== "confirmed") {
      // Nobody wants a reminder for an appointment that is no longer happening.
      await cancelByDedupeKey(tx, `booking.reminder:${bookingId}`);
    }
    if (status === "cancelled") {
      await enqueue(tx, {
        businessId,
        topic: "booking.cancelled",
        payload: { bookingId },
        dedupeKey: `booking.cancelled:${bookingId}`,
      });
      // The time is free again — offer it down the waitlist before it goes
      // back into public stock. Enqueued rather than called directly: keeps
      // this transaction pure SQL, and keeps booking.ts free of a dependency
      // on waitlist.ts (which already depends on this file).
      await enqueue(tx, {
        businessId,
        topic: "waitlist.slot_freed",
        payload: {
          staffId: updated.staffId,
          serviceId: updated.serviceId,
          startMs: updated.startAt.getTime(),
          endMs: updated.endAt.getTime(),
        },
        dedupeKey: `waitlist.freed:${bookingId}`,
      });
    }
  });
  await publishCalendar(businessId, { type: "booking.updated", bookingId });
}

export async function staffForService(businessId: string, serviceId: string) {
  const links = await db
    .select({ staffId: s.staffServices.staffId })
    .from(s.staffServices)
    .where(eq(s.staffServices.serviceId, serviceId));
  if (links.length === 0) return [];
  return db
    .select({ id: s.staff.id, name: s.staff.name })
    .from(s.staff)
    .where(
      and(
        eq(s.staff.businessId, businessId),
        eq(s.staff.isActive, true),
        inArray(s.staff.id, links.map((l) => l.staffId)),
      ),
    );
}
import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { createBooking } from "@/lib/booking";
import { businessBySlug, clientIp } from "@/lib/public";
import { rateLimit } from "@/lib/ratelimit";

const body = z.object({
  serviceId: z.uuid(),
  staffId: z.uuid(),
  startMs: z.number().int(),
  endMs: z.number().int(),
  holdToken: z.string().min(16),
  name: z.string().trim().min(1).max(100),
  phone: z.string().trim().regex(/^\+?\d{10,15}$/),
});

export async function POST(req: NextRequest, ctx: { params: Promise<{ slug: string }> }) {
  const { slug } = await ctx.params;
  if (!(await rateLimit(`book:${await clientIp()}`, 10, 60))) {
    return NextResponse.json({ error: "rate_limited" }, { status: 429 });
  }
  const parsed = body.safeParse(await req.json().catch(() => null));
  if (!parsed.success) return NextResponse.json({ error: "bad_request" }, { status: 400 });
  const biz = await businessBySlug(slug);
  if (!biz) return NextResponse.json({ error: "not_found" }, { status: 404 });

  const { serviceId, staffId, startMs, endMs, holdToken, name, phone } = parsed.data;
  const result = await createBooking({
    businessId: biz.id,
    staffId,
    serviceId,
    slot: { startMs, endMs },
    holdToken,
    client: { name, phone },
  });
  if (!result.ok) {
    return NextResponse.json({ error: result.error }, { status: 409 });
  }
  return NextResponse.json({ bookingId: result.bookingId });
}
import {
  boolean,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  smallint,
  text,
  time,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

// Admin users (owner or staff member with a login). Clients don't log in.
export const users = pgTable("users", {
  id: uuid("id").primaryKey().defaultRandom(),
  email: text("email").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
  name: text("name").notNull(),
  role: text("role", { enum: ["owner", "staff"] }).notNull().default("staff"),
  businessId: uuid("business_id").references(() => businesses.id),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const businesses = pgTable("businesses", {
  id: uuid("id").primaryKey().defaultRandom(),
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  timezone: text("timezone").notNull().default("Asia/Almaty"),
  currency: text("currency").notNull().default("KZT"),
  // How long a picked slot is held in Redis before checkout expires
  holdTtlSec: integer("hold_ttl_sec").notNull().default(300),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

// Opening hours per ISO weekday (1 = Monday … 7 = Sunday). No row = closed.
export const businessHours = pgTable(
  "business_hours",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    businessId: uuid("business_id").notNull().references(() => businesses.id, { onDelete: "cascade" }),
    weekday: smallint("weekday").notNull(), // 1-7 ISO
    openTime: time("open_time").notNull(), // local wall time, e.g. 09:00
    closeTime: time("close_time").notNull(),
  },
  (t) => [uniqueIndex("business_hours_unique").on(t.businessId, t.weekday)],
);

export const staff = pgTable("staff", {
  id: uuid("id").primaryKey().defaultRandom(),
  businessId: uuid("business_id").notNull().references(() => businesses.id, { onDelete: "cascade" }),
  userId: uuid("user_id").references(() => users.id), // optional login for this master
  name: text("name").notNull(),
  isActive: boolean("is_active").notNull().default(true),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

// Personal schedule overriding business hours. No rows = inherits business hours.
export const staffHours = pgTable(
  "staff_hours",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    staffId: uuid("staff_id").notNull().references(() => staff.id, { onDelete: "cascade" }),
    weekday: smallint("weekday").notNull(), // 1-7 ISO
    startTime: time("start_time").notNull(),
    endTime: time("end_time").notNull(),
  },
  (t) => [uniqueIndex("staff_hours_unique").on(t.staffId, t.weekday)],
);

export const services = pgTable("services", {
  id: uuid("id").primaryKey().defaultRandom(),
  businessId: uuid("business_id").notNull().references(() => businesses.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  durationMin: integer("duration_min").notNull(),
  priceKzt: integer("price_kzt").notNull(),
  isActive: boolean("is_active").notNull().default(true),
});

// Which masters perform which services (M:N)
export const staffServices = pgTable(
  "staff_services",
  {
    staffId: uuid("staff_id").notNull().references(() => staff.id, { onDelete: "cascade" }),
    serviceId: uuid("service_id").notNull().references(() => services.id, { onDelete: "cascade" }),
  },
  (t) => [primaryKey({ columns: [t.staffId, t.serviceId] })],
);

export const clients = pgTable(
  "clients",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    businessId: uuid("business_id").notNull().references(() => businesses.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    phone: text("phone").notNull(),
    email: text("email"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex("clients_business_phone_unique").on(t.businessId, t.phone)],
);

export const bookingStatuses = ["confirmed", "completed", "cancelled", "no_show"] as const;
export type BookingStatus = (typeof bookingStatuses)[number];

export const bookings = pgTable("bookings", {
  id: uuid("id").primaryKey().defaultRandom(),
  businessId: uuid("business_id").notNull().references(() => businesses.id, { onDelete: "cascade" }),
  staffId: uuid("staff_id").notNull().references(() => staff.id),
  serviceId: uuid("service_id").notNull().references(() => services.id),
  clientId: uuid("client_id").notNull().references(() => clients.id),
  startAt: timestamp("start_at", { withTimezone: true }).notNull(),
  endAt: timestamp("end_at", { withTimezone: true }).notNull(),
  status: text("status", { enum: bookingStatuses }).notNull().default("confirmed"),
  priceKzt: integer("price_kzt").notNull(), // snapshot of service price at booking time
  note: text("note"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const waitlistStatuses = ["waiting", "offered", "booked", "expired", "cancelled"] as const;

/**
 * A client who wants a day that is already full. When a booking is cancelled
 * the freed slot is offered down this queue, oldest entry first, each offer
 * held for a limited time before it moves on.
 */
export const waitlistEntries = pgTable(
  "waitlist_entries",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    businessId: uuid("business_id").notNull().references(() => businesses.id, { onDelete: "cascade" }),
    serviceId: uuid("service_id").notNull().references(() => services.id, { onDelete: "cascade" }),
    // null = any master who performs the service
    staffId: uuid("staff_id").references(() => staff.id, { onDelete: "cascade" }),
    clientId: uuid("client_id").notNull().references(() => clients.id, { onDelete: "cascade" }),
    dateISO: text("date_iso").notNull(), // local date at the business, YYYY-MM-DD
    status: text("status", { enum: waitlistStatuses }).notNull().default("waiting"),
    // Set while an offer is outstanding
    offerToken: text("offer_token"),
    // Redis hold reserving the slot for this client while the offer stands
    offerHoldToken: text("offer_hold_token"),
    offerSlotStartAt: timestamp("offer_slot_start_at", { withTimezone: true }),
    offerSlotEndAt: timestamp("offer_slot_end_at", { withTimezone: true }),
    offerExpiresAt: timestamp("offer_expires_at", { withTimezone: true }),
    offerStaffId: uuid("offer_staff_id").references(() => staff.id, { onDelete: "set null" }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("waitlist_offer_token_unique").on(t.offerToken),
    index("waitlist_queue_idx").on(t.businessId, t.dateISO, t.status, t.createdAt),
  ],
);

export const outboxStatuses = ["pending", "processing", "sent", "dead", "cancelled"] as const;

/**
 * Transactional outbox. Rows are written in the same transaction as the
 * business change they describe, so a booking and its confirmation can never
 * disagree about whether they happened. A worker drains them separately.
 */
export const outbox = pgTable(
  "outbox",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    businessId: uuid("business_id").notNull().references(() => businesses.id, { onDelete: "cascade" }),
    topic: text("topic").notNull(), // booking.confirmed, booking.reminder, waitlist.offer, …
    payload: jsonb("payload").notNull(),
    // Natural key of the thing this message is about. Lets callers enqueue
    // idempotently and cancel a scheduled message that is no longer wanted.
    dedupeKey: text("dedupe_key"),
    availableAt: timestamp("available_at", { withTimezone: true }).notNull().defaultNow(),
    status: text("status", { enum: outboxStatuses }).notNull().default("pending"),
    attempts: integer("attempts").notNull().default(0),
    maxAttempts: integer("max_attempts").notNull().default(5),
    lastError: text("last_error"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("outbox_dedupe_key_unique").on(t.dedupeKey),
    index("outbox_claim_idx").on(t.status, t.availableAt),
  ],
);

/** Everything a channel actually delivered — the demo's stand-in for an ESP. */
export const messageLog = pgTable("message_log", {
  id: uuid("id").primaryKey().defaultRandom(),
  businessId: uuid("business_id").notNull().references(() => businesses.id, { onDelete: "cascade" }),
  outboxId: uuid("outbox_id").references(() => outbox.id, { onDelete: "set null" }),
  channel: text("channel", { enum: ["email", "sms"] }).notNull(),
  recipient: text("recipient").notNull(),
  subject: text("subject").notNull(),
  body: text("body").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const auditLog = pgTable("audit_log", {
  id: uuid("id").primaryKey().defaultRandom(),
  businessId: uuid("business_id").notNull().references(() => businesses.id, { onDelete: "cascade" }),
  actorUserId: uuid("actor_user_id").references(() => users.id),
  action: text("action").notNull(), // e.g. booking.create, booking.cancel, service.update
  entity: text("entity").notNull(),
  entityId: uuid("entity_id"),
  meta: jsonb("meta"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});
